// Preserve the source verbatim and normalize only the working copy.
for (const item of $input.all()) {
  const j = item.json;
  const original = typeof j.Ticket === 'string' ? j.Ticket : JSON.stringify(j.Ticket ?? j);
  let schema = j['JSON Extract'] ?? {};
  if (typeof schema === 'string') {
    try { schema = JSON.parse(schema); }
    catch (e) { throw new Error('JSON Extract is not valid JSON: ' + e.message); }
  }
  if (!original.trim()) throw new Error('Ticket source is empty');
  if (!schema || typeof schema !== 'object' || Array.isArray(schema)) throw new Error('JSON Extract must be a JSON object');
  j.original_source = original;
  j.normalized_text = original.replace(/\r\n/g, '\n').replace(/[\t ]+/g, ' ').trim();
  j.extraction_schema = schema;
  j.received_at = new Date().toISOString();
}
return $input.all();
